examples.code:
new WireframeComponentDef
{
    Type        = "StatusBadge",
    Category    = "Custom",
    DisplayName = "Status Badge",
    DefaultWidth  = 80,
    DefaultHeight = 24,
    RenderSvg   = (el, b) =>
    {
        var color = el.Props.GetString("color", "#22c55e");
        b.AddMarkupContent(0,
            $"<rect width='{el.W}' height='{el.H}' rx='{el.H/2}' fill='{color}' opacity='0.15' stroke='{color}' stroke-width='1'/>"
            + $"<text x='{el.W/2}' y='{el.H/2}' fill='{color}' text-anchor='middle' dominant-baseline='middle' font-size='10'>Active</text>");
    },
    Props = [
        new PropDef { Name = "color", DisplayName = "Color", Type = PropType.Color, Default = "#22c55e", Category = "Appearance" }
    ]
}
